# code: (name_uk, p, m, h, w) — 53 programs from the gadalkindom.ru catalogue missing on the site
NEW = {
"19-9-10":("Чистий потік енергії","Сила, мудрість і вдача, що підтримують одна одну; ясність і внутрішнє світло.","Розпорошення енергії, ізоляція, очікування удачі без дій.","Енергія тече вільно, коли людина живе усвідомлено й не тримається за контроль.","Довіряти потоку, діяти вчасно, ділитися знаннями й радістю."),
"5-10-5":("Науковець","Системне мислення, жага знань, уміння пояснювати закони світу.","Догматизм, закритість у теоріях, страх змін.","Знання шукають порядок у випадковостях і перевіряють усе досвідом.","Досліджувати, навчати, поєднувати теорію з практикою."),
"18-22-4":("Розтоптана віра","Здатність відновити віру після розчарувань, свобода від чужих рамок.","Розчарування в людях і системах, страх довіряти, жорсткий контроль.","Колись віру зламали обставини чи сильніші люди — тепер важко довіряти.","Відновлювати віру поступово, будувати власну опору, працювати зі страхами."),
"11-4-15":("Амбіції і жага перемоги","Сила волі, лідерство, енергія досягати великого.","Боротьба за владу, тиск, перемога будь-якою ціною.","Сильне бажання бути першим може як вести до вершин, так і руйнувати стосунки.","Спрямовувати амбіції в чесну справу, рахуватися з людьми."),
"22-10-6":("Погана компанія","Відкритість людям, легкість у знайомствах, уміння бачити хороше.","Вплив сумнівного оточення, залежність від компанії, ризиковані розваги.","Людина легко потрапляє під вплив оточення й повторює чужі вибори.","Обирати оточення свідомо, вчитися казати «ні»."),
"4-17-13":("Капсулювання, поховане","Вміння зберегти цінне, глибина, здатність відродити забуте.","Закопані таланти й почуття, застиглість, страх змін.","Щось важливе колись «законсервували» — талант, мрію чи почуття.","Відкопувати своє: таланти, мрії, почуття — і давати їм життя."),
"3-18-15":("Найкраще або найгірше","Сильна інтуїція, творча уява, привабливість.","Ілюзії, залежності, самообман, крайнощі.","Життя йде між двома полюсами: надзвичайні злети або глибокі падіння.","Перевіряти бажання реальністю, обирати світло свідомо."),
"15-10-13":("Взаємодія","Уміння домовлятися й трансформувати ситуації, удача в змінах.","Маніпуляції, різкі розриви, залежність від обставин.","Через взаємодію з людьми приходять головні зміни й можливості.","Будувати чесні партнерства, відпускати те, що віджило."),
"19-5-4":("Переоцінка сил","Енергія, лідерство, віра в себе, авторитет.","Самовпевненість, гординя, непосильні зобов’язання.","Людина часто бере на себе більше, ніж може витримати.","Тверезо оцінювати ресурс, просити допомоги, делегувати."),
"20-4-6":("Енергія пристрасті","Сила почуттів, сімейність, уміння будувати союз.","Пристрасть, що руйнує, ревнощі, контроль у стосунках.","Почуття дуже сильні — вони можуть і будувати, і руйнувати.","Спрямовувати пристрасть у творення, домовлятися в парі."),
"4-19-15":("Багатоваріантність успіху","Лідерство, харизма, багато шляхів до достатку.","Розпорошення, жадібність, спокуса легких грошей.","Успіх можливий у різних сферах — важливо не розпорошитися.","Обрати головний напрямок, тримати чесність у грошах."),
"6-16-10":("Музей або доступ до цінностей","Цінування прекрасного, уміння зберігати й відкривати цінне.","Зациклення на минулому, страх змін, закритість.","Цінності можна законсервувати в «музеї», а можна зробити живими.","Ділитися цінностями, оновлювати традиції."),
"6-12-6":("Жертва заради любові","Відданість, глибина почуттів, здатність любити безумовно.","Жертовність, залежність, втрата себе в стосунках.","Заради любові людина готова відмовитися від себе.","Любити, не жертвуючи собою, ставити межі."),
"16-9-20":("Реформатор традицій","Сміливість змінювати застаріле, мудрість роду, глибина.","Конфлікти з рідними, руйнування традицій без заміни.","Людина приходить оновити родові правила й підходи.","Зберігати цінне, змінювати застаріле з повагою."),
"19-10-9":("Мандрівний мудрець","Мудрість, удача в подорожах, відкритість світу.","Неприкаяність, утеча від відповідальності, самотність.","Знання приходять через подорожі, зміни й досвід.","Мандрувати й ділитися досвідом, мати свій дім."),
"16-6-8":("У полоні любові","Сила почуттів, бажання справедливості в парі.","Залежні стосунки, руйнування через ревнощі, несправедливість.","Почуття стають кліткою, з якої важко вийти.","Будувати стосунки на рівності, виходити із залежності."),
"4-20-20":("Вершитель доль","Сила роду, лідерство, вплив на долі людей.","Владність, осуд, контроль над рідними.","Людина впливає на долі інших — у родині чи суспільстві.","Використовувати вплив відповідально, служити роду."),
"3-6-9":("Філантроп","Щедрість, любов до людей, мудрість.","Жертовність, роздавання себе, самотність.","Людині природно допомагати й ділитися.","Допомагати, зберігаючи ресурс для себе."),
"15-15-3":("Фатальна привабливість","Сильна харизма, сексуальність, здатність притягувати.","Маніпуляції, залежні стосунки, руйнівна пристрасть.","Привабливість дуже сильна і може як надихати, так і руйнувати.","Використовувати чарівність чесно, поважати почуття інших."),
"12-5-20":("Жертва заради мрії","Відданість ідеї, терпіння, духовність.","Жертва власним життям заради чужих правил чи мрій.","Людина відкладає своє життя заради далекої мети.","Йти до мрії, не відмовляючись від себе тут і зараз."),
"12-9-15":("Усвідомлені жертви","Мудрість, служіння, глибина.","Залежності, самопожертва, внутрішня боротьба.","Жертви робляться свідомо, але можуть вести до виснаження.","Розрізняти служіння й самознищення."),
"2-13-11":("Тренер","Інтуїція, сила, уміння вести через зміни.","Жорсткість, тиск, руйнування заради результату.","Людина допомагає іншим ставати сильнішими.","Навчати, підтримувати, поважати темп інших."),
"8-19-11":("Господар своєї долі","Сила, справедливість, успіх.","Самовпевненість, тиск, вигорання.","Людина здатна сама будувати свою долю.","Брати відповідальність, діяти чесно."),
"2-9-7":("Просвітлений","Мудрість, інтуїція, цілеспрямованість.","Відстороненість, самотність, гордість знаннями.","Людина шукає істину й глибину.","Ділитися мудрістю, жити в світі, а не над ним."),
"2-6-22":("Безрозсудний романтик","Чуттєвість, свобода, романтика.","Безвідповідальність у коханні, ілюзії, утеча.","Почуття ведуть, а розум відстає.","Поєднувати романтику з відповідальністю."),
"13-19-6":("Життя без вигорання","Відродження, радість, любов.","Вигорання, різкі зміни, втрата радості.","Сили відновлюються через любов і радість.","Берегти ресурс, вчасно відпускати зайве."),
"13-3-17":("Метаморфози долі","Здатність перетворюватися, творчість, надія.","Страх змін, втрата себе, розчарування.","Життя складається з етапів глибоких змін.","Приймати зміни, творити нове."),
"19-6-5":("Вогонь любові","Тепло, радість, гармонія в сім’ї.","Гординя в стосунках, потреба захоплення.","Любов — головне джерело сили.","Дарувати тепло, будувати сім’ю на повазі."),
"21-11-8":("Творець нової реальності","Масштаб, сила, справедливість.","Тиск, боротьба, руйнування.","Людина здатна змінювати світ навколо себе.","Діяти чесно, будувати нове."),
"21-6-3":("Любов без кордонів","Широке серце, любов до світу, творчість.","Ревнощі, залежність, розпорошення почуттів.","Любов не знає меж — і це може бути як даром, так і викликом.","Любити вільно, зберігаючи вірність собі."),
"22-8-4":("В'язниця","Почуття порядку, справедливості, стабільність.","Несвобода, обмеження, жорсткі рамки.","Людина опиняється в рамках — зовнішніх чи внутрішніх.","Шукати свободу всередині себе, виходити із застиглих схем."),
"3-11-8":("Успішний правитель","Сила, справедливість, достаток.","Владність, контроль, гординя.","Людина вміє керувати й досягати.","Керувати справедливо й щедро."),
"2-11-9":("Прихований потенціал","Сила, мудрість, інтуїція.","Нерозкриті таланти, самотність, страхи.","Великі здібності залишаються прихованими.","Відкривати свої таланти, довіряти собі."),
"2-12-10":("Незвичайний талант","Інтуїція, нестандартність, вдача.","Жертовність, пасивність, незатребуваність.","Талант незвичайний і потребує особливого шляху.","Цінувати свою незвичайність, шукати свою нішу."),
"2-14-12":("Смирення й очікування","Терпіння, гармонія, мудрість.","Пасивність, жертовність, застій.","Людина вміє чекати, але може чекати надто довго.","Поєднувати терпіння з дією."),
"2-15-13":("Перехід на темний бік","Глибина, сила, здатність до трансформації.","Залежності, маніпуляції, руйнування.","Сильна спокуса темного шляху.","Обирати світло свідомо, працювати з тінню."),
"2-16-14":("Зламаний баланс","Інтуїція, здатність відновлюватися, гармонія.","Кризи, руйнування, втрата рівноваги.","Баланс часто порушується через раптові події.","Відновлювати рівновагу, піклуватися про себе."),
"2-17-15":("Згубна мрія","Творчість, натхнення, харизма.","Ілюзії, залежності, нездійсненні мрії.","Мрія може надихати або руйнувати.","Перевіряти мрії реальністю, діяти поступово."),
"2-20-18":("Жриця Місяця","Інтуїція, родова мудрість, містичність.","Страхи, ілюзії, родові таємниці.","Сильний зв’язок з інтуїцією та родом.","Розвивати інтуїцію, відпускати родові страхи."),
"2-8-6":("Зріла любов","Мудрість у стосунках, справедливість, гармонія.","Холодність, розрахунок, сумніви.","Любов приходить через зрілість і досвід.","Будувати стосунки на рівності й повазі."),
"3-10-7":("Життя в достатку","Плідність, удача, рух уперед.","Марнотратство, лінощі, залежність від везіння.","Достаток приходить легко, якщо є рух.","Примножувати, а не розтрачувати."),
"3-14-11":("Ні багатства, ні бідності","Баланс, сила, гармонія.","Середній рівень через страх ризику.","Життя тримається в золотій середині.","Додавати сміливості, виходити за межі звичного."),
"3-16-13":("Випробування нуждою","Здатність відновлюватися, сила, трансформація.","Втрати, нужда, страх бідності.","Через нестачу людина вчиться цінувати ресурс.","Будувати фінансову подушку, працювати зі страхом нестачі."),
"3-17-14":("Скромна велич","Творчість, гармонія, внутрішня сила.","Недооцінювання себе, прихований талант.","Велич проявляється тихо, без гучності.","Показувати свій талант світу."),
"3-8-5":("Випробування достатком","Достаток, справедливість, мудрість.","Жадібність, контроль, марнотратство.","Гроші випробовують цінності.","Використовувати достаток для добра."),
"3-9-6":("Неприйняття свого тіла (краси)","Глибина, чуттєвість, внутрішня краса.","Неприйняття себе, комплекси, самотність.","Людина не бачить своєї краси.","Приймати й любити своє тіло."),
"4-10-6":("Тягар керівника","Відповідальність, лідерство, вміння керувати.","Перевантаження, самотність, втома.","Лідерство дається важко.","Ділити відповідальність, делегувати."),
"4-11-7":("Охоронець порядку","Сила, дисципліна, рішучість.","Жорсткість, контроль, агресія.","Людина захищає порядок і правила.","Захищати без жорстокості."),
"4-20-16":("Втрата влади й контролю","Сила роду, здатність відбудуватися.","Втрата контролю, кризи, конфлікти з батьками.","Влада може раптово втрачатися.","Будувати опору всередині себе."),
"4-6-20":("Влада любові","Сила, сімейність, любов.","Контроль через любов, владність у сім’ї.","Любов і влада тісно переплетені.","Любити, не контролюючи."),
"6-18-12":("Залежні стосунки","Чуттєвість, глибина, відданість.","Залежність, ілюзії, жертовність.","Стосунки часто будуються на залежності.","Будувати здорові межі, виходити з ролі жертви."),
"7-17-10":("Шлях до відомості","Цілеспрямованість, талант, удача.","Гонитва за славою, вигорання.","Дорога до визнання відкрита.","Йти до визнання через справжню творчість."),
"10-5-13":("Перегляд звичних шаблонів","Мудрість, здатність змінюватися, удача.","Застрягання в шаблонах, страх змін.","Життя спонукає переглядати правила.","Оновлювати переконання, пробувати нове."),
}
